#!/usr/bin/env node
// FILENAME: app/scripts/gen-sheet-name-case-table.mjs
// PURPOSE: Regenerate app/src/api/sheetNameCaseTable.generated.ts from the ONE
//          source of truth, the Rust table `EXCEL_SHEET_NAME_CASE_TABLE` in
//          core/identity/src/sheet_name_case.rs (Excel's sheet-name case rule,
//          measured live). The direction is fixed Rust -> TypeScript: never edit
//          the generated file by hand, and never edit the Rust table to match it.
// USAGE:   node app/scripts/gen-sheet-name-case-table.mjs
//          (app/src/api/__tests__/sheetNameCaseDrift.test.ts fails, naming this
//          script, whenever the two disagree.)

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const here = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(here, "../..");
const RUST = path.join(REPO, "core/identity/src/sheet_name_case.rs");
const OUT = path.join(REPO, "app/src/api/sheetNameCaseTable.generated.ts");

/** Parse the Rust table into [from, representative] code-point pairs. Shared
 *  logic with the drift test, which re-implements it on purpose (a test that
 *  imports the generator would agree with a generator bug). */
export function parseRustTable(src) {
  const start = src.indexOf("pub static EXCEL_SHEET_NAME_CASE_TABLE");
  if (start < 0) throw new Error("EXCEL_SHEET_NAME_CASE_TABLE not found in " + RUST);
  const declared = /\[\(char, char\); (\d+)\]/.exec(src.slice(start));
  const end = src.indexOf("];", start);
  const body = src.slice(start, end);
  const rows = [];
  const re = /\('\\u\{([0-9A-Fa-f]+)\}', '\\u\{([0-9A-Fa-f]+)\}'\)/g;
  let m;
  while ((m = re.exec(body)) !== null) rows.push([parseInt(m[1], 16), parseInt(m[2], 16)]);
  if (!declared || Number(declared[1]) !== rows.length) {
    throw new Error(`parsed ${rows.length} rows but the Rust type declares ${declared && declared[1]}`);
  }
  return rows;
}

const hex = (n) => "0x" + n.toString(16).toUpperCase();

function render(rows) {
  const lines = [];
  for (let i = 0; i < rows.length; i += 6) {
    lines.push("  " + rows.slice(i, i + 6).map(([a, b]) => `[${hex(a)}, ${hex(b)}]`).join(", ") + ",");
  }
  return [
    "//! FILENAME: app/src/api/sheetNameCaseTable.generated.ts",
    "// GENERATED by app/scripts/gen-sheet-name-case-table.mjs from",
    "// core/identity/src/sheet_name_case.rs (EXCEL_SHEET_NAME_CASE_TABLE). DO NOT EDIT.",
    "// Excel's sheet-name case rule, measured live: (code point, class representative)",
    "// for every character Excel treats as the same sheet-name character as another.",
    "// sheetNameCaseDrift.test.ts diffs this against the Rust file at test time.",
    "",
    `export const EXCEL_SHEET_NAME_CASE_TABLE: ReadonlyArray<readonly [number, number]> = [`,
    ...lines,
    "];",
    "",
  ].join("\n");
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const rows = parseRustTable(fs.readFileSync(RUST, "utf8"));
  fs.writeFileSync(OUT, render(rows), "utf8");
  console.log(`[OK] wrote ${rows.length} rows to ${path.relative(REPO, OUT)}`);
}
